PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  url:  <http://schema.org/>

SELECT  ?var1Label ?var2 ?var3 ?var4 ?var5 ?var6
WHERE
  { OPTIONAL
      { wde:Q456  rdfs:label  ?var1Label
        FILTER ( lang(?var1Label) = ?var7 )
        VALUES ( ?var7 ?var8 ) {
          ( "en" 1 )
          ( "en" 2 )
          ( "de" 3 )
          ( "fr" 4 )
          ( "it" 5 )
        }
      }
    OPTIONAL
      { wde:Q456  wdt:P18  ?var3 }
    OPTIONAL
      { wde:Q456  <urn:dboabstract>  ?var2
        FILTER ( lang(?var2) = "en" )
      }
    OPTIONAL
      { wde:Q456  wdt:P625  ?var4 }
    OPTIONAL
      { ?var6  rdf:type        url:Article ;
               url:about       wde:Q456 ;
               url:inLanguage  "en" ;
               url:isPartOf    <https://en.wikipedia.org/>
      }
  }
ORDER BY ASC(?var8)

