PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT  ?var1 ?var2 ?var3 ?var4
WHERE
  {   { ?var5  wdt:P106  wde:Q36180 }
    UNION
      { ?var5  wdt:P106  wde:Q482980 }
    UNION
      { ?var5  wdt:P106  wde:Q49757 }
    ?var5  wdt:P27   ?var6 ;
           wdt:P569  ?var3 ;
           wdt:P570  ?var4
    { ?var5  wdt:P1412  wde:Q1321 }
    OPTIONAL
      { ?var5  rdfs:label  ?var1
        FILTER ( lang(?var1) = "es" )
        ?var5  rdfs:label  ?var2
        FILTER ( lang(?var2) = "es" )
      }
  }
GROUP BY ?var2 ?var1 ?var3 ?var4

