                  { SELECT  (MIN(?v5) AS ?v8) (MAX(?v5) AS ?v9)
                    WHERE
                      { BIND(year(?v1) AS ?v5)
                        ?v2  wdt:P50   wde:Q6832207 ;
                                wdt:P577  ?v1
                      }
                  }
